$f=$pdo->query('SELECT * FROM cw_formulations WHERE id='.$id)->fetch();$v=$pdo->query('SELECT * FROM cw_formulation_versions WHERE formulation_id='.$id.' ORDER BY version_no DESC LIMIT 1')->fetch();$b['id']=$id;$b['version_token']=fc_version_token($f,$v);$b['source_token']=fc_calculate($b,fc_sources($pdo,$b))['source_token'];$b['approve']=true;$b['request_id']='formulation-test-request-0002';$approved=fc_save($pdo,$b);fc_test($approved['version']===2,'Approval appends version');
$old=$pdo->query('SELECT * FROM cw_formulation_versions WHERE formulation_id='.$id.' AND version_no=2')->fetch();$f=$pdo->query('SELECT * FROM cw_formulations WHERE id='.$id)->fetch();$b['version_token']=fc_version_token($f,$old);$b['approve']=false;$b['ingredients']=[];$b['request_id']='formulation-test-request-0003';fc_save($pdo,$b);
